import "server-only";

/**
 * Self-hosted Noto Sans Hebrew, embedded as base64 woff2 so the quote
 * PDF/HTML document (built by src/server/pdf/quote-template.ts and
 * rendered by Playwright's own Chromium in src/server/pdf/render.ts,
 * entirely outside Next's own App Router page-rendering pipeline) never
 * depends on an OS-installed font or a live request to Google Fonts at
 * render time.
 *
 * `next/font/google` (the project's normal convention, see the Cairo font
 * in src/app/layout.tsx) only self-hosts fonts for a React tree that Next
 * itself renders and manages <head> for — it has no way to hand raw font
 * bytes to a hand-assembled HTML string like this one, which Playwright
 * renders in total isolation from the Next.js request/response cycle. So
 * this file fetches the same Google Fonts source next/font/google would
 * (https://fonts.googleapis.com/css2?family=Noto+Sans+Hebrew), once, at
 * implementation time, and vendors the bytes below — same self-hosting
 * principle (no runtime Google dependency, works offline, identical in
 * dev/Docker/anywhere), adapted to a file next/font/google itself cannot
 * reach.
 *
 * Only the "hebrew" and "latin" Google Fonts subsets are embedded — the
 * quote template never needs Cyrillic/Greek — at weights 400 and 700,
 * the only two weights src/server/pdf/quote-template.ts's CSS uses.
 * "hebrew" covers Hebrew script (U+0590-05FF) and the ₪ sign (U+20AA);
 * "latin" covers the ASCII digits/punctuation used throughout the
 * template (quote numbers, dates, money).
 */

const NOTO_SANS_HEBREW_400_HEBREW = "";
const NOTO_SANS_HEBREW_400_LATIN = "";
const NOTO_SANS_HEBREW_700_HEBREW = "";
const NOTO_SANS_HEBREW_700_LATIN = "";

const HEBREW_UNICODE_RANGE =
  "U+0307-0308, U+0590-05FF, U+200C-2010, U+20AA, U+25CC, U+FB1D-FB4F";
const LATIN_UNICODE_RANGE =
  "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD";

function fontFace(weight: 400 | 700, unicodeRange: string, base64: string): string {
  return `
  @font-face {
    font-family: "Noto Sans Hebrew";
    font-style: normal;
    font-weight: ${weight};
    font-display: swap;
    unicode-range: ${unicodeRange};
    src: url(data:font/woff2;base64,${base64}) format("woff2");
  }`;
}

/** The full set of @font-face rules for the embedded Hebrew font — inline
 * this into the quote PDF template's <style> block when rendering a
 * Hebrew-language quote (src/server/pdf/quote-template.ts). Not used for
 * Arabic quotes, which keep their existing, unrelated font stack
 * untouched. */
export function hebrewFontFaceCss(): string {
  return [
    fontFace(400, HEBREW_UNICODE_RANGE, NOTO_SANS_HEBREW_400_HEBREW),
    fontFace(400, LATIN_UNICODE_RANGE, NOTO_SANS_HEBREW_400_LATIN),
    fontFace(700, HEBREW_UNICODE_RANGE, NOTO_SANS_HEBREW_700_HEBREW),
    fontFace(700, LATIN_UNICODE_RANGE, NOTO_SANS_HEBREW_700_LATIN),
  ].join("\n");
}
